<?php
declare(strict_types=1); use DecisionRules\RuleSetRepository;
require __DIR__.'/_auth.php'; $auth->requireAnyRole(['ADMIN','RULE_EDITOR','RULE_APPROVER','VIEWER']);
$repo=new RuleSetRepository($pdo); $sets=$repo->all(); $draft=$repo->draft(); $active=$repo->active(); $title='Rule Sets';$activePage='rule_sets';require __DIR__.'/partials/header.php';
?>
<section class="panel"><div class="panel-head"><div><h2>Version history</h2><p>Production evaluation uses only the Active Rule Set.</p></div><?php if($auth->hasRole('RULE_EDITOR')&&$active):?><?php if($draft):?><a class="btn secondary" href="rule_set_view.php?id=<?=(int)$draft['id']?>">Open existing Draft</a><?php else:?><a class="btn primary" href="rule_set_draft.php">Create New Draft</a><?php endif;?><?php endif;?></div><div class="table-wrap"><table><thead><tr><th>Version</th><th>Name</th><th>Status</th><th>Rules</th><th>Created By</th><th>Created At</th><th>Actions</th></tr></thead><tbody><?php foreach($sets as $set):?><tr><td><strong>v<?=(int)$set['version']?></strong></td><td><?=e($set['name']?:'—')?></td><td><span class="badge <?=$set['status']==='ACTIVE'?'on':'off'?>"><?=e(str_replace('_',' ',$set['status']))?></span></td><td><?=(int)$set['rule_count']?></td><td><?=e($set['created_by_username']?:'System')?></td><td><?=e($set['created_at'])?></td><td><a href="rule_set_view.php?id=<?=(int)$set['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php';?>
